# concepts:
# maximal_contiguous_runs, target_color_detection, row_column_analysis

# description:
# Given an input grid of arbitrary size filled with various colors, identify the longest contiguous runs of 
# a specified target color in each row and column. The output grid will highlight these maximal runs in maroon color, 
# while other cells remain black.

def main(input_grid: np.ndarray, target_color: str) -> np.ndarray:
    # Initialize the output grid with black color
    output_grid = np.full_like(input_grid, Color.BLACK)

    # Analyze rows for maximal contiguous runs
    for i in range(input_grid.shape[0]):
        max_run_start, max_run_end = None, None
        current_run_start = None

        for j in range(input_grid.shape[1]):
            if input_grid[i, j] == target_color:
                if current_run_start is None:
                    current_run_start = j
            else:
                if current_run_start is not None:
                    run_length = j - current_run_start
                    if max_run_start is None or run_length > (max_run_end - max_run_start):
                        max_run_start, max_run_end = current_run_start, j
                    current_run_start = None

        if current_run_start is not None:
            run_length = input_grid.shape[1] - current_run_start
            if max_run_start is None or run_length > (max_run_end - max_run_start):
                max_run_start, max_run_end = current_run_start, input_grid.shape[1]

        if max_run_start is not None:
            output_grid[i, max_run_start:max_run_end] = Color.MAROON

    # Analyze columns for maximal contiguous runs
    for j in range(input_grid.shape[1]):
        max_run_start, max_run_end = None, None
        current_run_start = None

        for i in range(input_grid.shape[0]):
            if input_grid[i, j] == target_color:
                if current_run_start is None:
                    current_run_start = i
            else:
                if current_run_start is not None:
                    run_length = i - current_run_start
                    if max_run_start is None or run_length > (max_run_end - max_run_start):
                        max_run_start, max_run_end = current_run_start, i
                    current_run_start = None

        if current_run_start is not None:
            run_length = input_grid.shape[0] - current_run_start
            if max_run_start is None or run_length > (max_run_end - max_run_start):
                max_run_start, max_run_end = current_run_start, input_grid.shape[0]

        if max_run_start is not None:
            output_grid[max_run_start:max_run_end, j] = Color.MAROON

    return output_grid


def generate_input() -> Tuple[np.ndarray, str]:
    # Random grid size from 5x5 to 10x10
    n, m = np.random.randint(5, 11), np.random.randint(5, 11)
    grid = np.random.choice(list(Color.NOT_BLACK), size=(n, m))

    # Choose target color from grid colors
    target_color = np.random.choice(grid.flatten())

    return grid, target_color

