# concepts:
# maximal_contiguous_runs, target_color_detection, row_column_analysis

# description:
# In the input grid, identify the longest contiguous segments of a specified target color in each row and column.
# For each row and column, highlight these maximal runs by replacing them with a different color (e.g., Color.YELLOW).
# If there are multiple maximal runs of the same length, highlight all of them.

def main(input_grid: np.ndarray) -> np.ndarray:
    target_color = Color.RED  # Target color to find maximal runs
    highlight_color = Color.YELLOW  # Color to highlight the maximal runs
    output_grid = input_grid.copy()

    # Analyze rows for maximal contiguous runs
    for i in range(input_grid.shape[0]):
        max_length = 0
        current_length = 0
        start_index = -1

        # Find maximal contiguous runs in the row
        for j in range(input_grid.shape[1]):
            if input_grid[i][j] == target_color:
                if current_length == 0:
                    start_index = j
                current_length += 1
            else:
                if current_length > max_length:
                    max_length = current_length
                current_length = 0

        # If the last run was the maximal, update max_length
        if current_length > max_length:
            max_length = current_length

        # Highlight the maximal runs in the row
        current_length = 0
        for j in range(input_grid.shape[1]):
            if input_grid[i][j] == target_color:
                if current_length == 0:
                    start_index = j
                current_length += 1
            else:
                if current_length == max_length:
                    output_grid[i, start_index:start_index + current_length] = highlight_color
                current_length = 0

        # Check if the last run should be highlighted
        if current_length == max_length:
            output_grid[i, start_index:start_index + current_length] = highlight_color

    # Analyze columns for maximal contiguous runs
    for j in range(input_grid.shape[1]):
        max_length = 0
        current_length = 0
        start_index = -1

        # Find maximal contiguous runs in the column
        for i in range(input_grid.shape[0]):
            if input_grid[i][j] == target_color:
                if current_length == 0:
                    start_index = i
                current_length += 1
            else:
                if current_length > max_length:
                    max_length = current_length
                current_length = 0

        # If the last run was the maximal, update max_length
        if current_length > max_length:
            max_length = current_length

        # Highlight the maximal runs in the column
        current_length = 0
        for i in range(input_grid.shape[0]):
            if input_grid[i][j] == target_color:
                if current_length == 0:
                    start_index = i
                current_length += 1
            else:
                if current_length == max_length:
                    output_grid[start_index:start_index + current_length, j] = highlight_color
                current_length = 0

        # Check if the last run should be highlighted
        if current_length == max_length:
            output_grid[start_index:start_index + current_length, j] = highlight_color

    return output_grid


def generate_input() -> np.ndarray:
    # Define grid size
    grid_size = np.random.randint(5, 15)
    grid = np.zeros((grid_size, grid_size), dtype=int)

    # Randomly fill the grid with the target color
    target_color = Color.RED
    other_colors = list(Color.NOT_BLACK - {target_color})

    for i in range(grid_size):
        for j in range(grid_size):
            if np.random.random() < 0.3:  # 30% chance of being the target color
                grid[i, j] = target_color
            else:
                grid[i, j] = np.random.choice(other_colors)

    return grid

