# concepts:
# color transformation, run modification, recoloring

# description:
# For each horizontal or vertical run of cyan (color-6), recolor up to 3 cells from each end to yellow (color-4).
# The number of cells recolored is capped at half the run length.

def main(input_grid: np.ndarray) -> np.ndarray:
    output_grid = input_grid.copy()

    # Helper function to recolor a run
    def recolor_run(start, end, is_horizontal):
        run_length = end - start + 1
        recolor_length = min(3, run_length // 2)
        if is_horizontal:
            # Recolor horizontally
            for i in range(recolor_length):
                output_grid[start + i] = Color.YELLOW
                output_grid[end - i] = Color.YELLOW
        else:
            # Recolor vertically
            for i in range(recolor_length):
                output_grid[:, start + i] = Color.YELLOW
                output_grid[:, end - i] = Color.YELLOW

    # Process horizontal runs
    for row in range(output_grid.shape[0]):
        start_idx = None
        for col in range(output_grid.shape[1]):
            if output_grid[row, col] == Color.TEAL:
                if start_idx is None:
                    start_idx = col
            elif start_idx is not None:
                recolor_run(start_idx, col - 1, is_horizontal=True)
                start_idx = None
        if start_idx is not None:
            recolor_run(start_idx, output_grid.shape[1] - 1, is_horizontal=True)

    # Process vertical runs
    for col in range(output_grid.shape[1]):
        start_idx = None
        for row in range(output_grid.shape[0]):
            if output_grid[row, col] == Color.TEAL:
                if start_idx is None:
                    start_idx = row
            elif start_idx is not None:
                recolor_run(start_idx, row - 1, is_horizontal=False)
                start_idx = None
        if start_idx is not None:
            recolor_run(start_idx, output_grid.shape[0] - 1, is_horizontal=False)

    return output_grid

def generate_input() -> np.ndarray:
    # Create a grid with dimensions between 5x5 and 15x15
    rows = np.random.randint(5, 16)
    cols = np.random.randint(5, 16)
    grid = np.random.choice(list(Color.NOT_BLACK), (rows, cols))

    # Randomly generate cyan runs
    num_runs = np.random.randint(1, 4)
    for _ in range(num_runs):
        is_horizontal = np.random.choice([True, False])

        if is_horizontal:
            row = np.random.randint(0, rows)
            start_col = np.random.randint(0, cols - 1)
            end_col = np.random.randint(start_col + 1, min(cols, start_col + 5))
            grid[row, start_col:end_col] = Color.TEAL
        else:
            col = np.random.randint(0, cols)
            start_row = np.random.randint(0, rows - 1)
            end_row = np.random.randint(start_row + 1, min(rows, start_row + 5))
            grid[start_row:end_row, col] = Color.TEAL

    return grid

