import numpy as np
from typing import *

# concepts:
# pattern matching, exact match, predicate evaluation

# description:
# In the input, you will see a grid with a pattern mask and a colored grid. The pattern mask denotes a specific pattern of cells
# that need to satisfy a certain predicate (e.g., being a particular color). The task is to identify whether the pattern mask
# exactly matches the predicate positions within the grid. If the match is exact, the output grid will have a single blue pixel; 
# otherwise, it will have a single red pixel.

def main(input_data):
    pattern_mask, color_grid = input_data

    # Determine where the pattern mask is True
    mask_coordinates = np.argwhere(pattern_mask)

    # Determine where the predicate (e.g., color is RED) holds in the color grid
    predicate_coordinates = np.argwhere(color_grid == Color.RED)

    # Check if the predicate coordinates exactly match the mask coordinates
    if set(map(tuple, mask_coordinates)) == set(map(tuple, predicate_coordinates)):
        return np.array([[Color.BLUE]])
    else:
        return np.array([[Color.RED]])

def generate_input():
    # Define grid size
    n, m = 5, 5

    # Generate a random pattern mask with True/False values
    pattern_mask = np.random.choice([False, True], size=(n, m), p=[0.7, 0.3])

    # Initialize a color grid
    color_grid = np.full((n, m), Color.BLACK)

    # Randomly choose positions to be RED, matching some of the pattern mask
    for x, y in np.argwhere(pattern_mask):
        if np.random.rand() > 0.5:
            color_grid[x, y] = Color.RED

    return (pattern_mask, color_grid)
